walk.content:
const s = JSON.parse(state);
const E = s.packages.engine;
const time = E.utilities.time.properties.state;
const kb = E.packages.controllers.utilities['keyboard-0'];
const pt = E.packages.controllers.utilities['pointer-0'];
const left = E.packages.controllers.utilities['xr-controller-left'];
const right = E.packages.controllers.utilities['xr-controller-right'];
const me = s.packages.player;
const d = me.properties.meta.data;
const dt = Math.min(time.delta, 0.1);
const radius = d.radius || 0.5;

const view = me.packages.head.utilities.camera.properties.state;
const vr = !!(view && view.presenting);

const keys = kb ? kb.properties.state.digital : [];
const struck = kb ? kb.properties.state.pressed : [];
const on = k => keys.indexOf(k) >= 0;
const hit = k => struck.indexOf(k) >= 0;

const stick = (pad, axis) => {
	if (!pad) return 0;
	const a = pad.properties.state.analog || {};
	return a[axis] || 0;
};

const pulled = (pad, name) => {
	if (!pad) return false;
	return pad.properties.state.digital.indexOf(name) >= 0;
};

const tapped = (pad, name) => {
	if (!pad) return false;
	return pad.properties.state.pressed.indexOf(name) >= 0;
};

let yaw = d.yaw || 0;
let pitch = d.pitch || 0;
let flying = d.flying ? 1 : 0;
let lift = d.lift || 0;
let fall = d.fall || 0;

// The heading the body is moved along. On the ground only the horizontal part
// is used; in the air all of it, so that looking up and flying forward climbs.
let fx = 0, fy = 0, fz = 0;
let rx = 0, rz = 0;
let ux = 0, uy = 0, uz = 0;

let ax = 0, ay = 0, az = 0;
let rate = 4.6;
let takeOff = false;
let land = false;

if (vr) {

	// --- the right stick turns
	const tx = stick(right, 'thumbstick-x');
	const ty = stick(right, 'thumbstick-y');

	yaw -= tx * 2.2 * dt;

	// The headset supplies where the eyes are pointed and the reference space
	// carries only a heading, so this is not a view pitch. In flight it is the
	// climb: the stick lifts and drops the body while the horizon stays level,
	// which is both the thing that can be done and the comfortable one.
	const climb = flying ? ty : 0;

	// --- the triggers begin and end flight
	if (tapped(right, 'trigger') && !flying) takeOff = true;
	if (tapped(left, 'trigger') && flying) land = true;

	// --- the left stick moves, along where the left controller points
	const mx = stick(left, 'thumbstick-x');
	const my = stick(left, 'thumbstick-y');

	const ray = left && left.properties.state.ray
		? left.properties.state.ray.direction : null;

	if (ray) {
		fx = ray[0]; fy = ray[1]; fz = ray[2];
	} else {
		fx = -Math.sin(yaw); fy = 0; fz = -Math.cos(yaw);
	}

	if (!flying) { fy = 0; }

	const far = Math.hypot(fx, fy, fz) || 1;
	fx /= far; fy /= far; fz /= far;

	// Right of the heading, kept level so that strafing never climbs.
	const side = Math.hypot(fz, -fx) || 1;
	rx = -fz / side; rz = fx / side;

	ax = fx * my + rx * mx;
	ay = fy * my + climb;
	az = fz * my + rz * mx;

	rate = pulled(left, 'squeeze') ? 11 : 4.6;

} else {

	if (pt) {
		const a = pt.properties.state.analog;
		yaw -= (a.dx || 0) * 3.2;
		pitch += (a.dy || 0) * 3.2;
		pitch = Math.max(-1.35, Math.min(1.35, pitch));
	}

	if (hit('Space') && !flying) takeOff = true;
	if ((on('ShiftLeft') || on('ShiftRight')) && flying) land = true;

	// The basis the body is steered along: forward carries the pitch, right
	// stays level, and up is what is left over, so that rising is always
	// square to where the eyes are pointed.
	const cp = Math.cos(pitch), sp = Math.sin(pitch);

	fx = -Math.sin(yaw) * cp;
	fy = sp;
	fz = -Math.cos(yaw) * cp;

	rx = Math.cos(yaw);
	rz = -Math.sin(yaw);

	// Up is right crossed with forward, and with right kept level it comes
	// out square to both: pressing E rises straight out of the top of the
	// view however the view is tilted.
	ux = -rz * fy;
	uy = rz * fx - rx * fz;
	uz = rx * fy;

	const ahead = (on('KeyW') || on('ArrowUp') ? 1 : 0) -
		(on('KeyS') || on('ArrowDown') ? 1 : 0);

	const aside = (on('KeyD') || on('ArrowRight') ? 1 : 0) -
		(on('KeyA') || on('ArrowLeft') ? 1 : 0);

	const climb = flying ? ((on('KeyE') ? 1 : 0) - (on('KeyQ') ? 1 : 0)) : 0;

	// On foot the pitch is not part of where the feet go.
	const gx = flying ? fx : -Math.sin(yaw);
	const gy = flying ? fy : 0;
	const gz = flying ? fz : -Math.cos(yaw);

	ax = gx * ahead + rx * aside + ux * climb;
	ay = gy * ahead + uy * climb;
	az = gz * ahead + rz * aside + uz * climb;

	// Shift is the brake on flight and the sprint on foot; it cannot be both
	// at once, and on the ground it is the sprint.
	rate = (!flying && (on('ShiftLeft') || on('ShiftRight'))) ? 12 : 4.6;
}

if (takeOff) { flying = 1; lift = 5.2; fall = 0; }
if (land) { flying = 0; lift = 0; fall = 0; }

const push = Math.hypot(ax, ay, az);
const drive = Math.min(1, push);

if (push > 1e-6) { ax /= push; ay /= push; az /= push; }

const probe = me.utilities.ground.properties.state;
const hits = probe ? probe.hits : null;
const surface = hits && hits.length ? hits[0] : null;

// Slope normalisation, on foot only: a climb costs ground covered rather than
// adding to the speed. In the air there is no surface to be normalised to.
let grade = 0;

if (!flying && surface && surface.normal && Math.abs(surface.normal[1]) > 1e-3) {
	const n = surface.normal;
	grade = -(ax * n[0] + az * n[2]) / n[1];
}

const step = Math.min(
	rate * drive * dt / Math.sqrt(1 + grade * grade),
	radius * 0.7
);

let px = d.position[0] + ax * step;
let pz = d.position[2] + az * step;
let py = d.position[1];

// Push out of anything solid already overlapped. Only the horizontal part of
// each normal is used, so being blocked can never raise the player.
const bump = me.utilities.bump.properties.state;

if (bump && bump.hits) {
	for (const hit of bump.hits) {
		const depth = radius - hit.distance;
		if (depth <= 0) continue;
		let nx = hit.normal[0];
		let nz = hit.normal[2];
		if (hit.distance < 0 && (ax !== 0 || az !== 0)) { nx = -ax; nz = -az; }
		const flat = Math.hypot(nx, nz);
		if (flat < 1e-4) continue;
		px += (nx / flat) * depth;
		pz += (nz / flat) * depth;
	}
}

const edge = 150;
px = Math.max(-edge, Math.min(edge, px));
pz = Math.max(-edge, Math.min(edge, pz));

const ground = surface ? surface.point[1] : null;
let lost = d.lost || 0;

if (flying) {

	// The jump that begins a flight decays into free movement.
	lift = Math.max(0, lift - 9 * dt);

	py += ay * step + lift * dt;

	// Never below what is underfoot, so a flight cannot be steered into the
	// ground and end up beneath it.
	if (ground != null && py < ground + 0.05) { py = ground + 0.05; }

	lost = 0;

} else if (ground == null) {

	// Nothing underneath. Fall, and if the probe cannot find anything at all
	// for a while, climb back to where it certainly can.
	fall -= 26 * dt;
	py += fall * dt;

	lost += 1;

	if (lost > 3) { py = 80; fall = 0; lost = 0; }

} else if (py > ground + 0.05) {

	// In the air over known ground: fall to it and land.
	fall -= 26 * dt;
	py += fall * dt;

	lost = 0;

	if (py <= ground) { py = ground; fall = 0; }

} else {

	py = Math.abs(ground - py) > 4 ? ground : py + (ground - py) * Math.min(1, 14 * dt);
	fall = 0;
	lost = 0;
}

if (py > 400 || py < -400) { py = 80; fall = 0; lost = 0; flying = 0; }

const moving = drive > 0.01 ? 1 : 0;
const moved = Math.hypot(
	px - d.position[0], py - d.position[1], pz - d.position[2]
);

const eye = d.eye || 1.75;

// On foot the head pitches and the body turns. In flight the whole body is
// tilted instead, so that the direction of travel and the view agree.
return JSON.stringify({ packages: { player: {
	properties: { meta: { data: {
		position: [px, py, pz],
		rotation: [0, yaw, 0],
		yaw: yaw,
		pitch: pitch,
		flying: flying,
		lift: lift,
		fall: fall,
		lost: lost,
		moving: moving,
		grade: grade,
		vr: vr ? 1 : 0,
		speed: dt > 0 ? moved / dt : 0,
		distance: (d.distance || 0) + (moving ? moved : 0)
	} } },
	packages: { head: {
		properties: { meta: { data: {
			position: vr ? [0, 0, 0] : [0, eye, 0],
			rotation: [vr ? 0 : pitch, 0, 0]
		} } },
		utilities: { camera: { properties: { data: { tilt: 0 } } } }
	} }
} } });

start.content:
const s = JSON.parse(state);
const display = s.packages.engine.utilities.display.properties.state;
const track = s.packages.ambience.utilities.track.properties;

if (!display.gesture) return;
if (!track.state || !track.state.loaded) return;
if (track.state.playing) return;
if (s.packages.ambience.properties.meta.data.started) return;

return JSON.stringify({ packages: { ambience: {
	properties: { meta: { data: { started: true } } },
	utilities: { track: { properties: { data: { play: true } } } }
} } });

lock.content:
const s = JSON.parse(state);
if (s.packages.engine.utilities.display.properties.data.cursor === 'locked') return;
return JSON.stringify({ packages: { engine: { utilities: { display: { properties: { data: { cursor: 'locked' } } } } } } });

settle.content:
const s = JSON.parse(state);
const marks = s.packages.landmarks.packages;
const patch = {};
let dirty = false;

Object.keys(marks).forEach(name => {
	const mark = marks[name];
	const data = mark.properties.meta.data;
	if (data.settled) return;
	const probe = mark.utilities.probe;
	if (!probe || !probe.properties.state) return;
	const hits = probe.properties.state.hits;
	if (!hits || !hits.length) return;
	const p = data.position;
	patch[name] = { properties: { meta: { data: {
		position: [p[0], hits[0].point[1] + (data.rise || 0), p[2]],
		settled: true
	} } }, utilities: { probe: null } };
	dirty = true;
});

if (!dirty) return;
return JSON.stringify({ packages: { landmarks: { packages: patch } } });

status.content:
const s = JSON.parse(state);
const E = s.packages.engine;
const time = E.utilities.time.properties.state;
const display = E.utilities.display.properties.state;
const hud = s.packages.hud;
const patch = { packages: { hud: { packages: {} , utilities: {} } } };
let dirty = false;

// The prompt is shown only while the pointer is free.
const wantPrompt = !display.locked && !display.xr.presenting;
if (hud.packages.prompt.properties.meta.data.enabled !== wantPrompt) {
	patch.packages.hud.packages.prompt = { properties: { meta: { data: { enabled: wantPrompt } } } };
	dirty = true;
}

// The readout is rebuilt on change, so it is refreshed a few times a second.
if (time.frame % 20 === 0) {
	const p = s.packages.player.properties.meta.data;
	const probe = s.packages.player.utilities.ground.properties.state;
	const ground = probe && probe.hits.length ? probe.hits[0].point[1].toFixed(0) : '--';
	const heading = Math.round(((-p.yaw * 180 / Math.PI) % 360 + 360) % 360);
	const v = s.packages.player.packages.head.utilities.camera.properties.state;
	if (p.vr) {
		const o = v && v.offset ? v.offset : [0, 0, 0];
		const line = (p.speed || 0).toFixed(1) + 'm/s   ' +
			Math.round(p.distance || 0) + 'm   grade ' + (p.grade || 0).toFixed(2) +
			'   pos ' + p.position.map(n => n.toFixed(0)).join(' ') +
			'   ' + (p.flying ? 'FLYING' : 'on foot');
		if (hud.utilities.readout.content !== line) {
			patch.packages.hud.utilities.readout = { content: line };
			dirty = true;
		}
		if (dirty) return JSON.stringify(patch);
		return;
	}
	const line = Math.round(p.distance || 0) + 'm   ' + heading + '\u00b0   ' + (p.speed || 0).toFixed(1) + 'm/s   ' + (p.flying ? 'flying  [shift] land  [Q/E] rise, dive' : 'on foot  [space] fly') + '   ' + display.fps + 'fps';
	if (hud.utilities.readout.content !== line) {
		patch.packages.hud.utilities.readout = { content: line };
		dirty = true;
	}
}

if (!dirty) return;
return JSON.stringify(patch);
